/* Care documentation, fictional names and explicitly synthetic treatment episodes. */
state.care??={};state.careHistory??=[];
const careSteps=[['triage','Triage & initial clinical assessment','Nursing / ED'],['risk','FN and risk assessment','Treating clinician'],['allergy','Allergy & renal review','Clinician / pharmacist'],['cultures','Blood cultures / specimen collection','Nursing / laboratory'],['orders','Treatment order reviewed','Clinician / pharmacist'],['dose','First antibiotic dose actually administered','Nursing'],['reassessment','Clinical reassessment','Treating clinician'],['disposition','Admission / observation / discharge decision','Treating clinician'],['followup','Follow-up and safety-net plan','Treating team']];
function patientName(p){if(p['Display name'])return p['Display name'];const pid=id(p),special={'WALK-LOW-01':'Youssef Adel','WALK-HIGH-01':'Mahmoud Samir','WALK-MISSING-01':'Omar Fathy'};if(special[pid])return special[pid];let n=/^FN-(\d+)$/.exec(pid);if(n){const ix=Number(n[1])-1,first=p.Sex==='Female'?['Mariam','Nour','Salma','Hana','Farida','Dina','Laila','Nada','Yasmin','Reem']:['Ahmed','Omar','Karim','Hassan','Mostafa','Ali','Tarek','Amr','Khaled','Youssef'];const last=['Adel','Samir','Fathy','Nabil','Saleh','Mansour','Kamal','Ibrahim','Farouk','Hamed','Rashad','Said','Maher','Soliman','Amin','Osman','Fawzy','Sabry','Mourad','Sherif'];return first[ix%10]+' '+last[Math.floor(ix/10)%20]}return 'Demo Patient '+pid.replace(/^DEMO-/,'')}
function patientLabel(p){return `${patientName(p)} · ${id(p)}`}
TABS.push('Treatment & disposition');
function emptyCare(){return{steps:{},treatment:null,disposition:null,followup:null}}
function careFor(pid){return state.care[pid]||emptyCare()}
function seedCare(){if(state.careSeedVersion===1)return;const now=Date.now(),at=h=>new Date(now+h*3600000).toISOString();for(const [pid,kind]of [['WALK-LOW-01','low'],['WALK-HIGH-01','high'],['WALK-MISSING-01','unknown']]){if(state.care[pid])continue;const c=emptyCare(),start=kind==='low'?-36:-5;for(let i=0;i<(kind==='unknown'?1:8);i++)c.steps[careSteps[i][0]]={status:'done',time:at(start+i*.1),by:careSteps[i][2]+' (fictional)',note:'Synthetic walkthrough event; not a clinical record'};
if(kind==='low'){c.steps.reassessment.time=at(-12);c.steps.disposition.time=at(-11);c.steps.followup={status:'done',time:at(-11),by:'Demo discharge team',note:'Follow-up arranged; appointment not yet attended'};c.treatment={regimen:'Ciprofloxacin + amoxicillin/clavulanate',route:'Oral',status:'Administered (synthetic)',orderedAt:at(-35.7),administeredAt:at(-35.5),note:'Fictional clinician-selected outpatient regimen after review of allergy, prior prophylaxis, oral tolerance and local resistance. No doses supplied.',recordedAt:at(-35.5)};c.steps.dose.time=c.treatment.administeredAt;c.disposition={status:'Discharged (synthetic)',time:at(-11),note:'Fictional reassessment after 25 hours: clinically stable; no additional high-risk feature recorded; oral intake, culture review and home support verified in scenario. MASCC alone did not authorize discharge.'};c.followup={status:'Scheduled',dueAt:at(13),contact:'Demo oncology clinic',note:'Next-day review; daily contact planned. Return urgently for deterioration, recurrent fever, inability to take medicines or new symptoms. Synthetic plan.'};}
if(kind==='high'){c.treatment={regimen:'Aztreonam + vancomycin',route:'IV',status:'Administered (synthetic)',orderedAt:at(-4.7),administeredAt:at(-4.5),note:'Fictional treating-team choice after review of reported penicillin urticaria. Dose, renal adjustment, monitoring and adequacy require pharmacy / ID review. Current culture identification is pending; no automatic treatment endorsement.',recordedAt:at(-4.5)};c.steps.dose.time=c.treatment.administeredAt;c.disposition={status:'Admitted (synthetic)',time:at(-4.2),note:'Inpatient monitoring for hypotension, profound neutropenia, renal impairment and suspected line infection. Oncology / ID consulted; ICU assessment requested in scenario.'};c.steps.disposition.time=c.disposition.time;c.steps.followup={status:'pending',time:null,by:'Treating team',note:'Inpatient reassessment ongoing; no outpatient discharge plan'};c.followup={status:'Inpatient reassessment',dueAt:at(1),contact:'Demo oncology / ID team',note:'Review haemodynamics, renal function, cultures and antimicrobial plan. Future review time is a demo task, not a universal protocol interval.'};}
state.care[pid]=c;state.careHistory.unshift({patientId:pid,time:new Date().toISOString(),action:'Seeded fictional '+kind+'-risk care episode'});}state.careSeedVersion=1;try{localStorage.setItem('fn-demo-v1',JSON.stringify(state))}catch{}}
seedCare();
function careChecklistView(){const pid=id(selected),c=careFor(pid),done=careSteps.filter(([k])=>c.steps[k]?.status==='done').length;return `<section class="panel"><div class="sectiontitle"><div><h2>Care checklist · ${esc(patientName(selected))}</h2><p>Documented ${done} / ${careSteps.length} steps · synthetic local episode</p></div><button class="btn" onclick="changeTab('Treatment & disposition')">Treatment & disposition →</button></div><div class="bar"><span style="width:${done/careSteps.length*100}%"></span></div>${careSteps.map(([k,label,owner])=>{const x=c.steps[k]||{status:'pending'};return `<div class="carestep"><span class="stepmark ${x.status==='done'?'done':''}">${x.status==='done'?'✓':'○'}</span><div class="stepcontent"><b>${label}</b><small>${owner}</small>${x.time?`<small>${esc(fmt(x.time))} · ${esc(x.by||'Demo user')}</small>`:''}${x.note?`<p>${esc(x.note)}</p>`:''}</div><span class="pill ${x.status==='done'?'':'amber'}">${esc(x.status)}</span><button class="btn" onclick="editCareStep('${k}')">${x.status==='done'?'Edit / undo':'Document'}</button></div>`}).join('')}<div class="quietnote">Completed = documented action, not confirmation that a result was normal or a treatment was appropriate. Reopen any step without deleting its audit history.</div></section>`}
function editCareStep(key){if(!selected)return;const step=careSteps.find(x=>x[0]===key);if(!step)return;const x=careFor(id(selected)).steps[key]||{};openDialog(step[1],`<form onsubmit="event.preventDefault();saveCareStep('${key}',this)"><label class="field">Status<select name="status">${['pending','done','deferred','not applicable'].map(s=>`<option ${x.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Event time (local)<input type="datetime-local" name="time" value="${localInput(x.time)}"></label><label class="field">Documented by<input name="by" maxlength="120" value="${esc(x.by||'Demo user')}"></label><label class="field">Note / reason<textarea name="note" maxlength="600">${esc(x.note||'')}</textarea></label><p>For done, record the actual demo event time. For deferred / not applicable, provide a reason. No clinical orders are sent.</p><p id="careError" role="alert"></p><div class="actions"><button class="btn primary" type="submit">Save step</button><button class="btn" type="button" onclick="closeDialog()">Cancel</button></div></form>`)}
function localInput(t){if(!t)return '';const d=new Date(t);if(!Number.isFinite(d.getTime()))return '';return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function validateCareStep(status,time,note){if(!['pending','done','deferred','not applicable'].includes(status))throw Error('Invalid status');if(status==='done'&&(!time||!Number.isFinite(Date.parse(time))))throw Error('Completed steps require a valid event time.');if(['deferred','not applicable'].includes(status)&&!note.trim())throw Error('Enter a reason.');return true}
function saveCareStep(key,form){try{const f=new FormData(form),status=String(f.get('status')),raw=String(f.get('time')||''),note=String(f.get('note')||'').trim();validateCareStep(status,raw,note);const pid=id(selected),c=state.care[pid]??=emptyCare(),before=c.steps[key]||null;const next={status,time:raw?new Date(raw).toISOString():null,by:String(f.get('by')||'Demo user').trim(),note};c.steps[key]=next;state.careHistory.unshift({patientId:pid,time:new Date().toISOString(),action:'Changed checklist '+key,before,after:{...next}});closeDialog();save('Care checklist '+key+' → '+status,pid)}catch(e){document.querySelector('#careError').textContent=e.message}}
function treatmentView(){const p=selected,pid=id(p),a=assess(p),c=careFor(pid),t=c.treatment,d=c.disposition,f=c.followup;return `<section class="panel"><div class="sectiontitle"><div><h2>Treatment & disposition</h2><p>${esc(patientName(p))} · recorded demo episode</p></div><button class="btn" onclick="editCarePlan()">Edit care record</button></div><div class="banner">Current assessment: ${badge(a.risk)} · This care episode is a saved fictional history. Input changes do not automatically rewrite treatment or disposition.</div><div class="grid2"><div class="card"><h3>◈ Treatment actually recorded</h3>${t?`<b>${esc(t.regimen)}</b><p>${esc(t.route)} · ${esc(t.status)}</p><p>Ordered: ${t.orderedAt?fmt(t.orderedAt):'Not recorded'}<br>Administered: ${t.administeredAt?fmt(t.administeredAt):'Not recorded'}</p><p>${esc(t.note)}</p>`:'<p>No treatment documented. No medication is inferred from risk alone.</p>'}</div><div class="card"><h3>↗ Disposition</h3>${d?`<b>${esc(d.status)}</b><p>${d.time?fmt(d.time):'Decision time not recorded'}</p><p>${esc(d.note)}</p>`:'<p>No admission / discharge decision recorded.</p>'}<h3>◷ Follow-up</h3>${f?`<b>${esc(f.status)}</b><p>${f.dueAt?fmt(f.dueAt):'No appointment time'} · ${esc(f.contact||'Team not recorded')}</p><p>${esc(f.note)}</p>`:'<p>No follow-up documented.</p>'}</div></div><details><summary>Pathway reference · proposed care versus recorded actions</summary><p>${a.risk==='High'?'High-risk guidance supports inpatient IV empirical therapy, prompt assessment and reassessment. Instability, resistance, allergy and organ function require individualized clinical review.':a.risk==='Low'?'Low-risk classification alone does not authorize discharge. Outpatient therapy requires clinical and logistical eligibility, observation, follow-up and clinician agreement.':'Complete assessment and obtain clinical review; missing data must not be interpreted as low risk.'}</p><p>Sources: <a href="https://www.idsociety.org/practice-guideline/neutropenic-patients-with-cancer/" target="_blank" rel="noopener">IDSA 2010</a> · <a href="https://www.idsociety.org/practice-guideline/fever-and-neutropenia-in-adults-with-cancer/" target="_blank" rel="noopener">ASCO/IDSA 2018</a> · supplied ESMO/AHS pathway. Local approval pending; conflicting source recommendations must be reconciled.</p><p>No dose calculator, prescription or automatic discharge authorization is enabled. Recorded demo drug examples are not patient-specific recommendations.</p></details><div class="actions"><button class="btn primary" onclick="changeTab('Care checklist')">Open care checklist</button><button class="btn" onclick="window.print()">Print care summary</button></div></section>`}
function editCarePlan(){const c=careFor(id(selected)),t=c.treatment||{},d=c.disposition||{},f=c.followup||{};openDialog('Edit fictional care record',`<form onsubmit="event.preventDefault();saveCarePlan(this)"><label class="field">Recorded treatment (optional)<input name="regimen" value="${esc(t.regimen||'')}" maxlength="180"></label><div class="grid2"><label class="field">Route<select name="route">${['Not recorded','IV','Oral','Other'].map(x=>`<option ${t.route===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Treatment state<select name="treatmentStatus">${['Not recorded','Planned (synthetic)','Ordered (synthetic)','Administered (synthetic)','Stopped (synthetic)'].map(x=>`<option ${t.status===x?'selected':''}>${x}</option>`).join('')}</select></label></div><label class="field">Order time<input name="orderedAt" type="datetime-local" value="${localInput(t.orderedAt)}"></label><label class="field">Actual administration time<input name="administeredAt" type="datetime-local" value="${localInput(t.administeredAt)}"></label><label class="field">Treatment context / review note<textarea name="treatmentNote" maxlength="800">${esc(t.note||'')}</textarea></label><label class="field">Disposition<select name="disposition">${['Not recorded','Under assessment (synthetic)','Observation (synthetic)','Admitted (synthetic)','Discharged (synthetic)'].map(x=>`<option ${d.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Disposition time<input name="dispositionTime" type="datetime-local" value="${localInput(d.time)}"></label><label class="field">Disposition reason / clinician review<textarea name="dispositionNote" maxlength="800">${esc(d.note||'')}</textarea></label><label class="field">Follow-up state<select name="followupStatus">${['Not arranged','Scheduled','Inpatient reassessment','Completed','Missed / needs contact'].map(x=>`<option ${f.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Follow-up time<input name="dueAt" type="datetime-local" value="${localInput(f.dueAt)}"></label><label class="field">Follow-up team<input name="contact" maxlength="120" value="${esc(f.contact||'')}"></label><label class="field">Follow-up / safety-net note<textarea name="followupNote" maxlength="800">${esc(f.note||'')}</textarea></label><p>Documentation of a fictional scenario only. Saving does not execute treatment or discharge, and does not mark checklist steps done.</p><p id="careError" role="alert"></p><div class="actions"><button class="btn primary" type="submit">Save fictional care record</button><button class="btn" type="button" onclick="closeDialog()">Cancel</button></div></form>`);document.querySelector('#workflowDialog').classList.add('assessmentdialog')}
function saveCarePlan(form){try{const f=new FormData(form),get=k=>String(f.get(k)||'').trim(),dt=k=>get(k)?new Date(get(k)).toISOString():null;const regimen=get('regimen'),status=get('treatmentStatus'),admin=dt('administeredAt'),ordered=dt('orderedAt');if(status==='Administered (synthetic)'&&(!regimen||!admin))throw Error('Administered status requires a treatment name and actual administration time.');if(admin&&ordered&&admin<ordered)throw Error('Administration cannot precede the recorded order.');const disp=get('disposition');if(disp==='Discharged (synthetic)'&&(!get('dispositionNote')||!get('dispositionTime')))throw Error('Document the discharge decision time and review context.');if(disp==='Discharged (synthetic)'&&assess(selected).risk!=='Low')throw Error('This demo does not finalize discharge documentation for High / Unknown risk. Record a clinician reassessment first.');const follow=get('followupStatus');if(['Scheduled','Inpatient reassessment','Completed'].includes(follow)&&!get('dueAt'))throw Error('Enter the follow-up / review time.');const pid=id(selected),c=state.care[pid]??=emptyCare(),before=JSON.parse(JSON.stringify(c));c.treatment=regimen?{regimen,route:get('route'),status,orderedAt:ordered,administeredAt:admin,note:get('treatmentNote'),recordedAt:new Date().toISOString()}:null;c.disposition={status:disp,time:dt('dispositionTime'),note:get('dispositionNote')};c.followup={status:follow,dueAt:dt('dueAt'),contact:get('contact'),note:get('followupNote')};state.careHistory.unshift({patientId:pid,time:new Date().toISOString(),action:'Updated fictional treatment / disposition / follow-up',before,after:JSON.parse(JSON.stringify(c))});closeDialog();save('Updated fictional care record (no clinical orders executed)',pid)}catch(e){document.querySelector('#careError').textContent=e.message}}
const detailBeforeCare=detail;detail=function(){let h=detailBeforeCare();if(selected){h=h.replace('<h1>'+id(selected)+' · ', '<h1>'+esc(patientName(selected))+' · ');if(patientTab==='Treatment & disposition')h+=treatmentView();}return h};
const auditBeforeCare=audit;audit=function(){let h=auditBeforeCare();return h+`<section class="panel" style="margin-top:20px"><h2>Care episode history</h2>${state.careHistory.slice(0,40).map(e=>`<div class="stage"><b>${esc(e.patientId)}</b> · ${esc(fmt(e.time))}<p>${esc(e.action)}</p></div>`).join('')||'<p>No care changes yet.</p>'}</section>`};
const exportBeforeCare=exportPatient;exportPatient=function(){download(id(selected)+'-care-demo.json',{synthetic:true,patient:{...selected,'Display name':patientName(selected)},assessment:assess(selected),care:careFor(id(selected)),results:latestResults(id(selected))});save('Exported synthetic patient and care record',id(selected))};
